param([string]$Out)
Add-Type -AssemblyName System.Drawing; $bmp = New-Object System.Drawing.Bitmap 256,256; $g = [System.Drawing.Graphics]::FromImage($bmp); $g.SmoothingMode = "AntiAlias"; $g.Clear([System.Drawing.ColorTranslator]::FromHtml("#12100E")); $gold = New-Object System.Drawing.SolidBrush ([System.Drawing.ColorTranslator]::FromHtml("#C6A15B")); $pen = New-Object System.Drawing.Pen ([System.Drawing.ColorTranslator]::FromHtml("#C6A15B")), 8; $g.DrawRectangle($pen, 18, 18, 220, 220); $font = New-Object System.Drawing.Font("Georgia", 150, ([System.Drawing.FontStyle]::Bold)); $fmt = New-Object System.Drawing.StringFormat; $fmt.Alignment = "Center"; $fmt.LineAlignment = "Center"; $g.DrawString("L", $font, $gold, (New-Object System.Drawing.RectangleF 0,0,256,256), $fmt); $g.Dispose(); $icon = [System.Drawing.Icon]::FromHandle($bmp.GetHicon()); $fs = [System.IO.File]::Create($Out); $icon.Save($fs); $fs.Close()